    if (!this.selectionHelper) {
      return;
    }
    if (this.selectionHelper.type === "Single") {
      console.warn("Calling selectPage in single selection mode have no effect");
      return;
    }
    if (requestedAction === "selectAll") {
      this.selectionHelper.selectAll();
      return;
    }
